var n=[{title:`Co způsobuje růst svalů`,text:`Svaly rostou v reakci na opakované mechanické zatížení a dostatečnou regeneraci. Velké změny obvykle trvají měsíce nebo roky, ne několik tréninků. Být silný a vypadat velmi svalnatě jsou různé výsledky a můžete si zvolit tréninkové cíle, které odpovídají tomu, co chcete.`},{title:`Co ukazují srovnávací studie`,text:`Metaanalýza z roku 2025 zjistila, že ženy a muži při srovnatelných programech silového tréninku získali zhruba podobnou relativní svalovou velikost, i když průměrné absolutní přírůstky mužů byly o něco větší. To není důvod odrazovat ženy od zvedání. Ukazuje to, že ženy mohou získat skutečné svaly a sílu.`},{title:`Trénujte pro to, co chcete`,text:`Někdo chce viditelný růst svalů. Jiným záleží víc na každodenní síle, zdraví kostí, sportovním výkonu nebo sebejistotě. Váš tréninkový objem a výběr cviků mohou těmito prioritami řídit. Silový trénink nevyžaduje kulturistické rutiny ani těžší váhy každý den.`},{title:`Příklad`,text:`Dva tréninky celého těla týdně s dřepy, přítahy, tlaky a hinge mohou zlepšit sílu a funkci. Sledujte svůj výkon a nebojte se, že jediný trénink náhle změní váš vzhled.`},{title:`Použití v TrainUp`,text:`V Profilu si zvolíte cíl: Celková kondice, Zesílit nebo Zlepšit vytrvalost. Váš plán se sestavuje z tohoto cíle, vaší úrovně, vybavení a zpětné vazby z tréninků a neslibuje žádný konkrétní tvar těla.`}];var o=[{label:`Systematický přehled z roku 2025: růst svalů u mužů a žen`,url:`https://pubmed.ncbi.nlm.nih.gov/40028215/`},{label:`Stanovisko ACSM z roku 2026`,url:`https://pubmed.ncbi.nlm.nih.gov/41843416/`}];var a={sections:n,sources:o};export{a as default,n as sections,o as sources};